void main() {
  group('closure of MockStreamHandlerEventSink does not hang', () {
    setUpAll(TestWidgetsFlutterBinding.ensureInitialized);

    const kTestEventChannelName = 'binary_messenger_test';

    setUp(() {
      void _onListen(
        final Object? rawArguments,
        final MockStreamHandlerEventSink events,
      ) {
        final arguments = rawArguments as Map<dynamic, dynamic>? ?? {};
        final close = arguments['close'] as bool? ?? false;

        if (close) {
          events.endOfStream();
        }
      }

      TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
          .setMockStreamHandler(
            EventChannel(kTestEventChannelName),
            MockStreamHandler.inline(onListen: _onListen),
          );
    });

    testWidgets('test finishes without hanging when sink is not closed', (
      final tester,
    ) async {
      EventChannel(
        kTestEventChannelName,
      ).receiveBroadcastStream({'close': false}).listen((_) {});
    });

    testWidgets('test finishes without hanging when sink is closed', (
      final tester,
    ) async {
      EventChannel(
        kTestEventChannelName,
      ).receiveBroadcastStream({'close': true}).listen((_) {});
    }, timeout: const Timeout(Duration(seconds: 1)));
  });
}

