class _ScrollDirectionListener extends StatefulWidget {
  const _ScrollDirectionListener({required this.child});
  final Widget child;
  @override
  State<_ScrollDirectionListener> createState() =>
      _ScrollDirectionListenerState();
}

class _ScrollDirectionListenerState extends State<_ScrollDirectionListener> {
  ScrollDirection _last = ScrollDirection.idle;
  @override
  Widget build(BuildContext context) {
    return NotificationListener<UserScrollNotification>(
