    FocusManager.instance.addListener(_onFocusChanged);
  }

  @override
  void dispose() {
    FocusManager.instance.removeListener(_onFocusChanged);
    super.dispose();
  }

  void _onFocusChanged() {
    if (mounted) setState(() {});
  }

  @override
  Widget build(BuildContext context) {
    final inset = MediaQuery.viewInsetsOf(context).bottom;
    final focus = FocusManager.instance.primaryFocus;
    final focused =
        focus?.hasPrimaryFocus == true &&
        focus?.context?.findAncestorStateOfType<EditableTextState>() != null;
    final bad = inset > 0 && !focused;
    return IgnorePointer(
      child: Material(
        color: bad ? Colors.red : Colors.black87,
        child: SafeArea(
          bottom: false,
          child: Padding(
            padding: const EdgeInsets.all(8),
            child: Text(
              'viewInsets.bottom = ${inset.toStringAsFixed(2)}\n'
              'text field focused: $focused'
              '${bad ? '\nINCONSISTENT: inset without focus' : ''}',
              style: const TextStyle(color: Colors.white, fontSize: 16),
            ),
          ),
        ),
      ),
    );
  }
}

class FirstPage extends StatelessWidget {
  const FirstPage({super.key});

  @override
  Widget build(BuildContext context) => Scaffold(
    appBar: AppBar(title: const Text('1 - has a text field')),
    body: Padding(
      padding: const EdgeInsets.fromLTRB(16, 96, 16, 16),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const TextField(
            decoration: InputDecoration(
              border: OutlineInputBorder(),
              labelText: 'tap me, then background the app',
            ),
          ),
          const SizedBox(height: 24),
          OutlinedButton(
            onPressed: () => FocusManager.instance.primaryFocus?.unfocus(),
            child: const Text('unfocus'),
          ),
          const SizedBox(height: 12),
          FilledButton(
            onPressed: () => Navigator.push(
              context,
              MaterialPageRoute(builder: (_) => const SecondPage()),
            ),
            child: const Text('second page (no text field)'),
          ),
        ],
      ),
    ),
  );
}

class SecondPage extends StatelessWidget {
  const SecondPage({super.key});

  @override
  Widget build(BuildContext context) => Scaffold(
    appBar: AppBar(title: const Text('2 - no text field')),
    body: Container(
      color: Colors.amber,
      child: Center(
        child: Text(
          'This amber area is the Scaffold body.\n'
          'It should reach the bottom of the screen.\n\n'
          'body height: '
          '${MediaQuery.sizeOf(context).height - MediaQuery.viewInsetsOf(context).bottom}',
          textAlign: TextAlign.center,
        ),
      ),
    ),
  );
}
```

</details>

