```dart
import 'package:flutter/gestures.dart';
import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:integration_test/integration_test.dart';

void main() {
  final binding = IntegrationTestWidgetsFlutterBinding.ensureInitialized();
  binding.framePolicy = LiveTestWidgetsFlutterBindingFramePolicy.fullyLive;

  testWidgets('second long-press after a route push mid-gesture', (tester) async {
    await tester.pumpWidget(MaterialApp(
      home: Scaffold(
        body: Builder(
          builder: (context) => ListTile(
            title: const Text('row'),
            onLongPress: () => showModalBottomSheet<void>(
              context: context,
              builder: (_) => const SizedBox(
                  height: 200, child: Center(child: Text('sheet'))),
            ),
          ),
        ),
      ),
    ));
    await tester.pump(const Duration(milliseconds: 300));

    Future<bool> longPressOpensSheet(int pointer) async {
      final gesture = await tester.startGesture(
          tester.getCenter(find.text('row')), pointer: pointer);
      // Real-time hold: the recognizer deadline is a real timer under the
      // live binding.
      final sw = Stopwatch()..start();
      while (sw.elapsedMilliseconds < 800) {
        await tester.pump(const Duration(milliseconds: 50));
        await Future<void>.delayed(const Duration(milliseconds: 50));
      }
      await gesture.up();
      final deadline = DateTime.now().add(const Duration(seconds: 3));
      while (DateTime.now().isBefore(deadline)) {
        await tester.pump(const Duration(milliseconds: 100));
        await Future<void>.delayed(const Duration(milliseconds: 100));
        if (find.text('sheet').evaluate().isNotEmpty) return true;
      }
      return false;
    }

    expect(await longPressOpensSheet(1), isTrue); // passes
    // close the sheet
    tester.state<NavigatorState>(find.byType(Navigator)).pop();
    await tester.pump(const Duration(seconds: 1));
    await Future<void>.delayed(const Duration(seconds: 1));

    expect(await longPressOpensSheet(2), isTrue); // FAILS
  });
}
```

