### Steps to reproduce

1. Create an app that uses a Checkbox widget or just `Semantics(checked: isChecked)`.
2. Run on Android and enable TalkBack.
3. Touch the checkbox to focus it with TalkBack

### Expected results

TalkBack should read "checked" if the checkbox is checked and "not checked" if not.

### Actual results

Reads "checked" but does not read "not checked".

### Code sample

<details open><summary>Code sample</summary>

```dart
import 'package:flutter/material.dart';

void main() {
  runApp(MyApp());
}

class MyApp extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      theme: ThemeData(useMaterial3: false),
      title: 'Flutter Demo',
      home: MyHomePage(title: 'Flutter Demo Home Page'),
    );
  }
}

class MyHomePage extends StatefulWidget {
  MyHomePage({Key? key, required this.title}) : super(key: key);

  final String title;

  @override
  _MyHomePageState createState() => _MyHomePageState();
}

class _MyHomePageState extends State<MyHomePage> {
  bool _isChecked = false;

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text(widget.title, style: TextStyle(fontFamily: 'ProductSans')),
      ),
      body: Center(
        child: CheckboxListTile(
          title: Text('Toggle me!'),
          value: _isChecked,
          onChanged: (value) {
            if (value == null) return;
            setState(() {
              _isChecked = value;
            });
          },
        ),
      ),
    );
  }
}
```

