issues.body:
### Steps to reproduce

A rebuild requested while a `LayoutBuilder` is laying out its own child is lost permanently in release builds. Nothing in that `LayoutBuilder`'s build scope rebuilds again until something else lays it out.

Self-contained test (`flutter test` in a fresh `flutter create` project). It **passes** on 3.47.4 — it asserts the buggy behaviour, so it can be used to bisect a fix:

```dart
// Release strips the asserts that make debug diverge, so this test turns off
// `debugBuildingDirtyElements` (the "Build scheduled during frame." throw, which
// fires *before* the scope is told) and catches the one mutation assert that
// fires exactly where release returns early. The framework state it leaves is
// the state a release build would have.
// ignore_for_file: invalid_use_of_protected_member
import 'package:flutter/rendering.dart';
import 'package:flutter/widgets.dart';
import 'package:flutter_test/flutter_test.dart';

/// Runs [onLayout] from inside its own layout - standing in for any code that
/// notifies during layout (see "A trigger that needs no misuse" below).
class RenderLayoutHook extends RenderProxyBox {
  RenderLayoutHook(this.onLayout, this.generation);
  VoidCallback onLayout;
  int generation;
  @override
  void performLayout() {
    onLayout();
    super.performLayout();
  }
}

class LayoutHook extends SingleChildRenderObjectWidget {
  const LayoutHook({super.key, required this.onLayout, required this.generation, super.child});
  final VoidCallback onLayout;
  final int generation;
  @override
  RenderLayoutHook createRenderObject(BuildContext context) =>
      RenderLayoutHook(onLayout, generation);
  @override
  void updateRenderObject(BuildContext context, RenderLayoutHook renderObject) {
    renderObject.onLayout = onLayout;
    if (renderObject.generation != generation) {
      renderObject
        ..generation = generation
        ..markNeedsLayout();
    }
  }
}

class Counter extends StatefulWidget {
  const Counter({super.key});
  @override
  State<Counter> createState() => CounterState();
}

class CounterState extends State<Counter> {
  int value = 0;
  int builds = 0;
  void bump() => setState(() => value++);
  @override
  Widget build(BuildContext context) {
    builds++;
    return Text('v$value', textDirection: TextDirection.ltr);
  }
}

void bumpFromLayout(WidgetTester tester, CounterState state) {
  final binding = tester.binding;
  final saved = binding.debugBuildingDirtyElements;
  binding.debugBuildingDirtyElements = false;
  try {
    state.bump();
  } on FlutterError catch (error) {
    if (!error.message.contains('was mutated in')) rethrow;
  } finally {
    binding.debugBuildingDirtyElements = saved;
  }
}

void main() {
  testWidgets('a rebuild asked for mid-layout under a LayoutBuilder is lost', (tester) async {
    final counterKey = GlobalKey<CounterState>();
    final width = ValueNotifier<double>(300);
    final generation = ValueNotifier<int>(0);
    var armed = false;
    var hookFired = false;

    final layoutBuilder = LayoutBuilder(
      builder: (context, constraints) => Column(
        children: [
          Counter(key: counterKey),
          ValueListenableBuilder<int>(
            valueListenable: generation,
            builder: (_, value, _) => LayoutHook(
              generation: value,
              onLayout: () {
                if (!armed) return;
                armed = false;
                hookFired = true;
                bumpFromLayout(tester, counterKey.currentState!);
              },
              child: const SizedBox(width: 10, height: 10),
            ),
          ),
        ],
      ),
    );

    await tester.pumpWidget(
      Directionality(
        textDirection: TextDirection.ltr,
        child: Center(
          child: ValueListenableBuilder<double>(
            valueListenable: width,
            child: layoutBuilder,
            builder: (_, w, child) => SizedBox(width: w, height: 300, child: child),
          ),
        ),
      ),
    );
    final state = counterKey.currentState!;
    final layoutBuilderBox = tester.renderObject(find.byType(LayoutBuilder)) as RenderBox;

    // 1. An ordinary rebuild under the LayoutBuilder works.
    state.bump();
    await tester.pump();
    expect(find.text('v1'), findsOneWidget);

    // 2. The frame that loses it: the hook is laid out from inside the
    // LayoutBuilder's layout and marks the counter dirty there.
    armed = true;
    generation.value = 1;
    await tester.pump();
    expect(hookFired, isTrue);
    final buildsAfterStrand = state.builds;
    expect(state.value, 2);
    expect(find.text('v1'), findsOneWidget, reason: 'the rebuild was lost');
    expect(layoutBuilderBox.debugNeedsLayout, isFalse);

    // 3. Frames alone never recover it.
    for (var i = 0; i < 5; i++) {
      await tester.pump(const Duration(milliseconds: 16));
    }
    expect(state.builds, buildsAfterStrand);

    // 4. A later setState from idle is dropped outright: the element is still
    // dirty, so markNeedsBuild returns before asking for anything.
    state.bump();
    expect(tester.binding.hasScheduledFrame, isFalse);
    await tester.pump(const Duration(milliseconds: 16));
    expect(state.builds, buildsAfterStrand);

    // 5. Rebuilding anything else inside that scope is dropped too.
    generation.value = 2;
    await tester.pump(const Duration(milliseconds: 16));
    expect(find.text('v1'), findsOneWidget);

    // 6. The latch: this setState is outside that scope entirely, and it still
    // asks for no frame.
    width.value = 280;
    expect(tester.binding.hasScheduledFrame, isFalse,
        reason: 'a root-scope setState scheduled nothing');
    await tester.pump();
    expect(layoutBuilderBox.size.width, 300, reason: 'no frame ran');

    // 7. Something else draws (here, by hand): the root flush clears the latch,
    // the new constraints lay the LayoutBuilder out, and the scope catches up.
